sealed class NucleoException(message: String): kotlin.Exception(message) {
        
        class Apertura(message: String) : NucleoException(message)
        
        class CredencialesInvalidas(message: String) : NucleoException(message)
        
        class UsuarioInactivo(message: String) : NucleoException(message)
        
    /**
     * Usuario global (sincronizado) que todavía no fijó contraseña en
     * este teléfono. `Nucleo::autenticar`/`autenticar_con_secreto`
     * interceptan esto internamente y redirigen a `autenticar_supabase`
     * (ver el comentario ahí) -- Kotlin nunca ve este error para un
     * usuario global. La variante sigue existiendo por el contrato FFI
     * -- confirmado en la auditoría 2026-09-24 (NR-07/NS-25) que el único
     * camino que fijaba contraseña con sólo la cédula era
     * `AppCore::fijar_password_inicial`, ya eliminada por no tener
     * llamadores reales; el alta de contraseña de un usuario global pasa
     * siempre por `autenticar_supabase` (Supabase Auth), así que esta
     * variante no debería escapar sin interceptar desde acá.
     */
        class SinPasswordLocal(message: String) : NucleoException(message)
        
        class NoAutenticado(message: String) : NucleoException(message)
        
    /**
     * La sesión de Supabase Auth (la de la PERSONA, distinta del token del
     * DISPOSITIVO) venció o nunca se abrió -- Kotlin debe mandar de vuelta
     * al login. Ver `Nucleo::cambiar_password_supabase`.
     */
        class SesionSupabaseVencida(message: String) : NucleoException(message)
        
        class FechaInvalida(message: String) : NucleoException(message)
        
    /**
     * El gafete ya está activo en este sitio del lado de OTRO
     * dispositivo -- chequeo en vivo (`application::registrar_ingreso_verificado`),
     * nunca llega a tocar `registrar_ingreso` en el núcleo, se corta acá
     * mismo. Reemplaza `GafeteOcupadoEnSitioException`, que antes vivía
     * sólo del lado de Kotlin (`PantallaConfirmarIngreso.kt`).
     */
        class GafeteOcupadoEnSitio(message: String) : NucleoException(message)
        
    /**
     * La cédula ya tiene un ingreso de proveedor abierto en OTRO sitio
     * (chequeo en vivo contra la nube, de mejor esfuerzo). Mismo texto que
     * `desktop/src-tauri/src/comandos/proveedores.rs`.
     */
        class ProveedorActivoEnOtroSitio(message: String) : NucleoException(message)
        
    /**
     * Una regla de negocio rechazó la operación (dato inválido, PRAIND
     * vencido, ...). `mensaje` ya viene listo para mostrar tal cual, sin
     * prefijo técnico -- sale de `control_acceso::mensajes`.
     */
        class Rechazado(message: String) : NucleoException(message)
        
        class Interno(message: String) : NucleoException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<NucleoException> {
        override fun lift(error_buf: RustBuffer.ByValue): NucleoException = FfiConverterTypeNucleoError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeNucleoError : FfiConverterRustBuffer<NucleoException> {
    override fun read(buf: ByteBuffer): NucleoException {
        
            return when(buf.getInt()) {
            1 -> NucleoException.Apertura(FfiConverterString.read(buf))
            2 -> NucleoException.CredencialesInvalidas(FfiConverterString.read(buf))
            3 -> NucleoException.UsuarioInactivo(FfiConverterString.read(buf))
            4 -> NucleoException.SinPasswordLocal(FfiConverterString.read(buf))
            5 -> NucleoException.NoAutenticado(FfiConverterString.read(buf))
            6 -> NucleoException.SesionSupabaseVencida(FfiConverterString.read(buf))
            7 -> NucleoException.FechaInvalida(FfiConverterString.read(buf))
            8 -> NucleoException.GafeteOcupadoEnSitio(FfiConverterString.read(buf))
            9 -> NucleoException.ProveedorActivoEnOtroSitio(FfiConverterString.read(buf))
            10 -> NucleoException.Rechazado(FfiConverterString.read(buf))
            11 -> NucleoException.Interno(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: NucleoException): ULong {
        return 4UL
    }

